-- Página do anúncio (/fazemos): visitas e cliques no WhatsApp contados pelo próprio site.
ALTER TABLE usage_events DROP CONSTRAINT IF EXISTS usage_events_event_name_check;
ALTER TABLE usage_events ADD CONSTRAINT usage_events_event_name_check CHECK (event_name IN ('site_visit', 'resume_started', 'pdf_print_requested', 'feedback_sent', 'donation_page_view', 'paywall_view', 'checkout_started', 'payment_approved', 'pricing_view', 'start_page_view', 'resume_imported', 'example_used', 'referral_visit', 'cover_letter_started', 'cover_letter_printed', 'docx_downloaded', 'service_requested', 'job_match_used', 'interview_view', 'applications_used', 'send_message_copied', 'linkedin_used', 'kit_gate_view', 'robot_test_used', 'ad_landing_view', 'whatsapp_click'));
